// UpdateConnection writes every mutable field; the caller passes the
// current values for fields it does not change. The revision guards
// against a concurrent change.
func (q *Queries) UpdateConnection(ctx context.Context, arg UpdateConnectionParams) (PcConnection, error) {
	row := q.db.QueryRow(ctx, updateConnection,
		arg.GatewayID,
		arg.BaseUrl,
		arg.AllowedHosts,
		arg.DestinationClass,
		arg.AccessMode,
		arg.DefaultMode,
		arg.MaxResponseBytes,
		arg.TimeoutMs,
		arg.State,
		arg.QuarantineReason,
		arg.UpdatedBy,
		arg.OrgID,
		arg.ID,
		arg.Revision,
	)
	var i PcConnection
	err := row.Scan(
		&i.OrgID,
		&i.ID,
		&i.Name,
		&i.Kind,
		&i.GatewayID,
		&i.Package,
		&i.BaseUrl,
		&i.AllowedHosts,
		&i.DestinationClass,
		&i.AccessMode,
		&i.CredentialHeader,
		&i.CredentialScheme,
		&i.DefaultMode,
		&i.MaxResponseBytes,
		&i.TimeoutMs,
		&i.State,
		&i.QuarantineReason,
		&i.Revision,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedBy,
		&i.UpdatedAt,
	)
	return i, err
}
